<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) &mdash; Piet Mondrian</title>
<meta name="description" content="Piet Mondrian's Composition with Red, Blue and Yellow (1930): De Stijl, Neoplasticism, and why its asymmetric balance of primary colours still matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800&family=Archivo+Black&display=swap" rel="stylesheet">
<style>
:root{
  --red:#d40000;
  --blue:#0033a0;
  --yellow:#f7d300;
  --black:#0a0a0a;
  --white:#f7f5f0;
  --grey:#6b6b6b;
  --line:14px;
  --maxw:1180px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  background:var(--white);
  color:var(--black);
  font-family:'Archivo',system-ui,sans-serif;
  font-size:clamp(16px,1.05vw + 12px,19px);
  line-height:1.55;
  -webkit-font-smoothing:antialiased;
}
h1,h2,h3,.display{font-family:'Archivo Black','Archivo',sans-serif;font-weight:400;letter-spacing:-.015em;line-height:1.02;margin:0}
p{margin:0 0 1em}
a{color:inherit}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 clamp(18px,4vw,48px)}

/* ---------- top rule ---------- */
.rule-top{display:flex;height:22px;gap:0}
.rule-top span{flex:1}
.rule-top .r{background:var(--red);flex:3}
.rule-top .b{background:var(--blue);flex:1}
.rule-top .y{background:var(--yellow);flex:1}
.rule-top .k{background:var(--black);flex:0 0 22px}

/* ---------- masthead ---------- */
header.mast{padding:clamp(28px,5vw,64px) 0 clamp(18px,3vw,32px)}
.kicker{
  font-weight:800;text-transform:uppercase;letter-spacing:.22em;font-size:.72rem;
  display:inline-flex;align-items:center;gap:12px;margin-bottom:clamp(14px,2vw,22px)
}
.kicker i{display:block;width:16px;height:16px;background:var(--red)}
h1{font-size:clamp(2.1rem,6.2vw,4.6rem);max-width:20ch}
.sub{margin-top:clamp(14px,2vw,22px);max-width:56ch;color:#212121;font-size:1.08rem}
.byline{
  display:flex;flex-wrap:wrap;gap:0 clamp(16px,2.4vw,34px);margin-top:clamp(20px,3vw,34px);
  border-top:var(--line) solid var(--black);padding-top:14px;font-weight:600;font-size:.86rem;
  text-transform:uppercase;letter-spacing:.08em
}
.byline b{color:var(--grey);font-weight:600}
.byline div{display:flex;gap:8px;align-items:baseline}

/* ---------- the composition ---------- */
section{padding:clamp(34px,6vw,80px) 0;border-top:var(--line) solid var(--black)}
.sec-head{display:flex;align-items:flex-start;gap:16px;margin-bottom:clamp(20px,3vw,38px)}
.sec-head .chip{flex:0 0 auto;width:26px;height:26px;margin-top:6px}
.sec-head h2{font-size:clamp(1.4rem,3.1vw,2.3rem)}

.stage{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(22px,3.4vw,52px);align-items:start}
@media (max-width:900px){.stage{grid-template-columns:1fr}}

/* painting built from a grid with black gaps = the lines */
.painting{
  position:relative;aspect-ratio:1/1;background:var(--black);
  border:var(--line) solid var(--black);box-shadow:18px 18px 0 rgba(10,10,10,.12)
}
.painting .cells{
  position:absolute;inset:0;display:grid;
  grid-template-columns:1fr 1.35fr;
  grid-template-rows:1.6fr 1fr;
  gap:var(--line)
}
.painting .cells i{display:block;background:var(--white)}
.painting .cells i.red{background:var(--red)}
.painting .cells i.blue{background:var(--blue)}
.painting .cells i.yellow{background:var(--yellow)}
figcaption{margin-top:14px;font-size:.84rem;color:var(--grey)}
figcaption b{color:var(--black)}

/* optional three.js relief */
#relief-wrap{margin-top:clamp(18px,2.4vw,28px);display:none}
#relief-wrap.on{display:block}
#relief{display:block;width:100%;aspect-ratio:16/9;background:var(--black)}

